# Viva deep redo — slot R4 (part B): reactive & drug eruptions, urticaria, tattoo (7 cases)
# Own words. Topics guided by the previous-year question book (Sahana P Raju) — classify urticaria, cold urticaria,
# annular erythemas, pustular eruptions, drug reactions; facts checked with IADVL 5e and current EAACI/WAO urticaria guideline.
PYQ = "Previous-year PG question papers (Sahana P Raju, Solved Papers Dermatology)"
IA = "IADVL Textbook of Dermatology 5e"

D = [
dict(case="Erythema multiforme", src=f"{PYQ}; {IA} (Erythema multiforme)",
 qa=[
 ("Define erythema multiforme (EM).", ["Acute, self-limited, often recurrent immune-mediated mucocutaneous reaction characterised by typical target lesions in an acral distribution, usually triggered by infection (most often HSV)", "EM minor (no or one mucosa mildly) and EM major (≥1 mucosa severely, more systemic upset); now considered separate from SJS/TEN"]),
 ("Causes.", ["Infections (~90%): herpes simplex (commonest — HSV-1 > HSV-2, appears 3–14 days after herpes), Mycoplasma pneumoniae (children; mucosa-dominant — MIRM), others (hepatitis C, EBV, orf, histoplasmosis, COVID-19)", "Drugs (<10%): NSAIDs, sulphonamides, antiepileptics, antibiotics", "Others: vaccines, radiotherapy, IBD, idiopathic"]),
 ("Describe a typical target lesion.", ["Round <3 cm with three distinct concentric zones and a well-defined border: central dusky/blistered or crusted disc, middle paler oedematous ring, outer erythematous ring", "Atypical raised target: only two zones, palpable, poorly defined edge (EM major)", "Atypical flat targets/purpuric macules with blisters = SJS/TEN pattern, not EM"]),
 ("Distribution and mucosal features.", ["Symmetrical, acral — backs of hands, palms, forearms, feet, elbows, knees, face; spreads centripetally; Koebner phenomenon; lesions appear in crops over 3–5 days and are fixed for ≥7 days (unlike urticaria)", "Mucosa: lips (haemorrhagic crusts), buccal mucosa erosions; eyes and genitals in major"]),
 ("Pathogenesis of HSV-associated EM.", ["HSV DNA fragments (polymerase gene, Pol) carried by CD34+ circulating cells to skin → expressed in keratinocytes → HSV-specific CD4 Th1 response with IFN-γ → cytotoxic damage", "HLA-DQ3 association in recurrent EM"]),
 ("Histopathology.", ["Interface dermatitis with vacuolar change, scattered necrotic keratinocytes (more than in other interface dermatoses), lymphocyte exocytosis, papillary oedema; sub-epidermal bulla in severe lesions; normal basket-weave stratum corneum (acute process)"]),
 ("Differential diagnosis.", ["Urticaria (transient wheals <24 h, no dusky centre — urticarial multiforme in children), SJS/TEN, fixed drug eruption (multiple), bullous pemphigoid (urticarial phase), Rowell syndrome (lupus + EM-like lesions with ANA, anti-Ro), Sweet syndrome, vasculitis, Kawasaki disease, serum sickness-like reaction, annular erythemas, polymorphic light eruption"]),
 ("What is Rowell's syndrome? (PYQ)", ["Lupus erythematosus (usually SCLE/DLE) with EM-like lesions, speckled ANA, anti-Ro/La, positive rheumatoid factor, chilblains — criteria by Zeitouni"]),
 ("Treatment.", ["Treat/remove trigger; symptomatic: antihistamines, topical steroids, oral antiseptic/anaesthetic mouthwashes and steroid gels for mucosa", "Severe mucosal: short course systemic steroids (controversial), ophthalmology care", "Recurrent HSV-associated EM: continuous suppressive acyclovir 400 mg twice daily (or valacyclovir 500 mg BD) for 6–12 months even if herpes not evident", "Refractory: dapsone, azathioprine, mycophenolate, thalidomide, apremilast, JAK inhibitors", "Mycoplasma: macrolide/doxycycline"]),
 ("Classify annular/figurate erythemas (PYQ: list annular erythemas).", ["Erythema annulare centrifugum (trailing scale), erythema marginatum (rheumatic fever), erythema migrans (Lyme), erythema gyratum repens (wood-grain; malignancy), EM, urticaria, SCLE, granuloma annulare, tinea, sarcoid, Hansen's, necrolytic migratory erythema (glucagonoma — 'migratory erythema')"]),
 ("What is MIRM?", ["Mycoplasma-induced rash and mucositis — children/young adults; prominent mucositis (oral, ocular, genital) with few or no skin lesions; good prognosis with macrolides and supportive care"]),
 ("Prognosis.", ["Self-limiting in 2–4 weeks without scarring; recurrences common in HSV-related EM; ocular sequelae rarely in major"]),
 ],
 spot=["Typical three-zone acral targets after herpes labialis — EM minor", "Recurrent EM — suppressive acyclovir"]),

dict(case="Erythema nodosum", src=f"{PYQ}; {IA} (Panniculitis)",
 qa=[
 ("Define erythema nodosum (EN).", ["Commonest panniculitis — acute, tender, red, warm subcutaneous nodules mainly on shins, a delayed hypersensitivity reaction to various antigens; resolves without ulceration or scarring"]),
 ("Causes (mnemonic: NODOSUM).", ["Idiopathic (30–50%)", "Infections: streptococcal pharyngitis (commonest in children), tuberculosis (important in India), Yersinia, Salmonella, Campylobacter, Chlamydia, Mycoplasma, histoplasmosis, coccidioidomycosis, hepatitis B/C, EBV, leprosy (ENL is different), COVID-19", "Drugs: oral contraceptives/oestrogens, sulphonamides, penicillin, bromides, isotretinoin, vemurafenib/BRAF inhibitors", "Systemic disease: sarcoidosis (Löfgren syndrome), inflammatory bowel disease (Crohn's > UC), Behçet's", "Pregnancy, malignancy (lymphoma, leukaemia)"]),
 ("Describe the clinical features.", ["Young women 20–40 y (F:M ~5:1); prodrome of fever, malaise, arthralgia", "Bilateral, symmetrical, tender, bright red, poorly defined nodules 1–5 cm on anterior shins, also knees, ankles, thighs, forearms", "Evolve like a bruise (contusiform): red → purple → yellow-green (erythema contusiformis) over 2 weeks; never ulcerate; crops for 3–6 weeks"]),
 ("What is Löfgren syndrome?", ["Acute sarcoidosis: EN + bilateral hilar lymphadenopathy + fever + migratory polyarthritis/periarticular ankle inflammation ± anterior uveitis; HLA-DRB1*03; excellent prognosis (spontaneous remission)"]),
 ("Histopathology.", ["Septal panniculitis without vasculitis — thickened oedematous septa with lymphocytes, neutrophils (early), histiocytes", "Miescher's radial granulomas (small histiocytes around a central stellate cleft) — hallmark", "Deep incisional biopsy needed (punch may miss fat)"]),
 ("Investigations to find the cause.", ["CBC, ESR/CRP, throat swab, ASO/anti-DNase B, Mantoux/IGRA, chest X-ray (TB, sarcoid hilar nodes), stool culture if diarrhoea, pregnancy test, serum ACE, IBD work-up (faecal calprotectin) if bowel symptoms, HBV/HCV"]),
 ("Differential diagnosis.", ["Erythema induratum/nodular vasculitis (calves, ulcerate, lobular panniculitis with vasculitis)", "ENL in leprosy (anywhere, evanescent, systemic signs, smear positive)", "Cellulitis (unilateral), superficial thrombophlebitis, cutaneous polyarteritis nodosa (livedo, nodules along vessels), lupus panniculitis, pancreatic panniculitis (ulcerate, oily discharge), α1-antitrypsin panniculitis, Sweet syndrome, subcutaneous lymphoma, insect bites"]),
 ("Treatment.", ["Treat the underlying cause; stop OCP/drug", "Bed rest, leg elevation, compression, NSAIDs (indomethacin, naproxen, ibuprofen)", "Potassium iodide 300–900 mg/day (SSKI) for 3–4 weeks — useful in persistent cases (avoid in pregnancy/thyroid disease)", "Colchicine, hydroxychloroquine, dapsone; systemic steroids only after excluding infection (TB) and when severe", "EN in IBD — treat the bowel disease"]),
 ("Differentiate septal from lobular panniculitis with examples.", ["Septal without vasculitis: EN, necrobiosis lipoidica, morphoea/scleroderma; septal with vasculitis: superficial thrombophlebitis, cutaneous PAN", "Lobular without vasculitis: lupus panniculitis, pancreatic, α1-antitrypsin, cold, factitial, sclerema/subcutaneous fat necrosis of newborn, lipodermatosclerosis; lobular with vasculitis: erythema induratum (nodular vasculitis), ENL"]),
 ("Prognosis?", ["Self-limited in 3–6 weeks; may recur (with recurrent streptococcal infection or persistent cause); chronic/migratory variants rare"]),
 ],
 spot=["Bilateral tender bruise-like shin nodules in a young woman — EN (never ulcerates)", "Miescher's radial granulomas", "EN + hilar nodes + arthritis — Löfgren syndrome"]),

dict(case="Fixed drug eruption", src=f"{PYQ}; {IA} (Cutaneous adverse drug reactions)",
 qa=[
 ("What is a fixed drug eruption (FDE)?", ["Drug eruption that recurs at exactly the same site(s) each time the drug is taken, often adding new sites — usually 30 min to 8 h after re-exposure (first exposure: 1–2 weeks)"]),
 ("Common culprit drugs (India).", ["Cotrimoxazole and sulphonamides, fluoroquinolones (ciprofloxacin, ofloxacin), NSAIDs (paracetamol, ibuprofen, oxicams, metamizole), tetracyclines, metronidazole/tinidazole, fluconazole, dapsone, barbiturates, phenolphthalein laxatives, carbamazepine", "Food and colours can cause it (fixed food eruption)"]),
 ("Describe the lesion.", ["One or a few sharply demarcated round/oval dusky red to violaceous plaques, may blister centrally; burning/itching", "Heals with persistent slate-grey/brown hyperpigmentation (more marked in dark skin) which darkens and enlarges with each episode", "Sites: lips, genitals (glans penis — commonest site in men), hands, feet, face, oral mucosa", "Variants: generalised bullous FDE (GBFDE — mimics SJS/TEN, elderly, can be fatal), non-pigmenting FDE (pseudoephedrine), linear, eczematous, urticarial, wandering"]),
 ("Pathogenesis — why does it recur at the same site?", ["Intra-epidermal resident memory CD8+ T cells (effector memory) persist at the healed site; on re-exposure they release IFN-γ, granzyme, perforin → keratinocyte death; regulatory T cells limit spread", "Explains the 'fixed' nature and rapid onset"]),
 ("Histopathology.", ["Interface dermatitis with many necrotic keratinocytes, mixed infiltrate including eosinophils and neutrophils, deep and superficial perivascular infiltrate, prominent pigment incontinence (melanophages) in dermis even in active lesions"]),
 ("How do you confirm the culprit drug?", ["Detailed drug history and timeline; drug causality assessment (Naranjo scale, WHO-UMC)", "Patch test on the previously affected site (lesional patch test) — positive in ~40%; safe", "Oral provocation test with small dose under supervision (not for GBFDE); avoid if severe"]),
 ("Differential diagnosis.", ["Genital: herpes simplex (recurrent vesicles, Tzanck/PCR), syphilitic chancre, Behçet's, traumatic ulcer", "Skin: EM (targets, acral), bullous insect bite, post-inflammatory hyperpigmentation, lichen planus pigmentosus, ashy dermatosis, mastocytoma, morphoea (early)", "GBFDE vs SJS/TEN: GBFDE has larger well-demarcated patches with intervening normal skin, less mucosal involvement, rapid onset, past history of similar episodes, better prognosis"]),
 ("Treatment.", ["Identify and stop the drug; give the patient a written list of culprit and cross-reacting drugs (drug card)", "Topical potent steroid for non-erosive lesions; antiseptic/wet dressings for erosions; antihistamines", "GBFDE: manage like SJS/TEN in a burn-unit setting (cyclosporine/supportive)", "Pigmentation fades slowly; avoid re-exposure"]),
 ("Why is cross-reactivity relevant?", ["Structurally related drugs (e.g. among fluoroquinolones, oxicam NSAIDs) may trigger the same lesions — test or avoid the whole class"]),
 ],
 spot=["Recurrent dusky plaque on glans at same site after drug — FDE", "Heals with slate-grey pigmentation", "Lesional patch test"]),

dict(case="Acute generalised exanthematous pustulosis (AGEP)", src=f"{PYQ}; {IA} (Cutaneous adverse drug reactions); EuroSCAR AGEP validation score",
 qa=[
 ("Define AGEP.", ["Acute severe cutaneous adverse reaction with rapid eruption of numerous small (<5 mm) non-follicular sterile pustules on oedematous erythema, fever and neutrophilia; >90% drug-induced"]),
 ("Common culprit drugs.", ["Aminopenicillins (amoxicillin, ampicillin) and other β-lactams, macrolides, quinolones, pristinamycin, sulphonamides, hydroxychloroquine (long latency), terbinafine, diltiazem, calcium-channel blockers, ketoconazole, carbamazepine", "Non-drug triggers: infections (enterovirus, parvovirus B19, CMV, Mycoplasma), spider bites, mercury"]),
 ("Clinical features.", ["Onset within 1–2 days of the drug (antibiotics; up to 1–3 weeks for some like HCQ)", "Burning/itchy erythema starting on face or intertriginous areas (axillae, groin) → spreads; hundreds of pinhead pustules; may have purpura, targetoid lesions, facial oedema; mucosal involvement mild in ~20% (only one site)", "Fever >38 °C, neutrophilia (>7×10⁹/L), mild eosinophilia; organ involvement (liver, kidney, lung) in ~20%", "Resolves in 1–2 weeks with collarette/punctate desquamation after stopping drug"]),
 ("Pathogenesis.", ["Drug-specific T cells (CD4, CD8) release CXCL8 (IL-8), IL-17, IL-22, GM-CSF → neutrophil recruitment to epidermis — type IVd hypersensitivity", "IL36RN mutations in some patients (link with generalised pustular psoriasis)"]),
 ("Histopathology.", ["Spongiform subcorneal and/or intra-epidermal pustules, papillary dermal oedema, perivascular infiltrate with neutrophils and eosinophils, necrotic keratinocytes; may have leukocytoclastic vasculitis", "Psoriasis features (regular acanthosis, tortuous vessels) absent"]),
 ("Differentiate AGEP from generalised pustular psoriasis (GPP).", ["AGEP: drug history, acute onset (days), no personal/family history of psoriasis, rapid resolution in <15 days after stopping drug, eosinophils and necrotic keratinocytes on histology, positive patch test sometimes", "GPP: history of psoriasis, slower evolution, recurrent, longer duration, arthritis, psoriasiform histology, IL36RN mutations"]),
 ("Other differentials of pustular eruption (PYQ: causes of pustular eruption).", ["GPP, subcorneal pustular dermatosis (Sneddon–Wilkinson — annular, flexural, chronic), IgA pemphigus, pustular vasculitis, DRESS with pustules, SJS/TEN early (pustular), bacterial folliculitis, candidiasis, pustular drug eruptions (acneiform, halogenoderma), infantile acropustulosis, erythema toxicum neonatorum, transient neonatal pustular melanosis"]),
 ("Diagnostic score.", ["EuroSCAR AGEP validation score (morphology, course, histology): ≥8 definite, 5–7 probable, 1–4 possible, ≤0 no AGEP"]),
 ("Management.", ["Stop the culprit drug (most important); supportive care — antipyretics, emollients, wet compresses", "Moderate/potent topical steroids for symptoms; systemic steroids (prednisolone 0.5–1 mg/kg) for severe disease or organ involvement; cyclosporine/infliximab rarely", "Avoid unnecessary antibiotics (pustules are sterile); patch test after recovery (positive in ~50%) — useful to confirm the drug", "Drug card and cross-reactivity counselling"]),
 ("Prognosis.", ["Excellent; mortality ~1–5% mainly in elderly with comorbidities or organ involvement"]),
 ],
 spot=["Hundreds of non-follicular pinhead pustules in flexures 1–2 days after amoxicillin — AGEP", "Resolves in <15 days with collarette desquamation"]),

dict(case="Tattoo & tattoo reactions", src=f"{PYQ}; {IA} (Tattoos, foreign-body reactions)",
 qa=[
 ("Classify tattoos.", ["Decorative/professional (cosmetic — permanent make-up of eyebrows, lips, eyeliner), amateur (Indian 'godna' — traditional), traumatic (asphalt/road-rash, gunpowder, coal miners, pencil lead), medical (radiotherapy marks, nipple-areola reconstruction, micro-pigmentation of scalp/vitiligo camouflage)", "Temporary: henna (natural, brownish-red) and 'black henna' (PPD-added — strong sensitiser)"]),
 ("Pigments and colours.", ["Black — carbon (Indian ink), iron oxide, logwood", "Red — mercuric sulphide (cinnabar), cadmium selenide, ferric oxide, organic azo dyes (now most common)", "Yellow — cadmium sulphide; green — chromium oxide; blue — cobalt aluminate; white — titanium dioxide, zinc oxide; brown — ferric oxide; purple — manganese"]),
 ("Classify tattoo reactions.", ["Acute: inflammatory (normal healing), infections — bacterial (S. aureus, Pseudomonas, non-tuberculous mycobacteria like M. chelonae from contaminated ink), viral (hepatitis B/C, HIV, HPV warts, molluscum), fungal; leprosy and syphilis historically", "Hypersensitivity: allergic contact dermatitis (red pigment commonest — cinnabar/azo), photo-allergic (yellow — cadmium), lichenoid, granulomatous (sarcoidal — may be first sign of systemic sarcoidosis), pseudolymphomatous", "Koebner phenomenon: psoriasis, lichen planus, vitiligo, DLE in tattoo", "Neoplastic: keratoacanthoma, SCC, BCC, melanoma (coincidental)", "Others: MRI-related burning/swelling (iron oxide), pigment migration to lymph nodes (mimics metastasis), 'blow-out' (pigment spread into fat), keloid"]),
 ("Why is 'black henna' dangerous?", ["Contains paraphenylenediamine (PPD) to darken and speed colour — causes severe allergic contact dermatitis (blisters, hypopigmentation/keloid in the tattoo shape) and lifelong sensitisation to hair dyes, textile dyes, sunscreens (PABA), local anaesthetics (benzocaine), sulphonamides (cross-reacting para-amino compounds)"]),
 ("Histopathology of tattoo reactions.", ["Pigment granules in macrophages and extracellularly in dermis; patterns: lichenoid interface, spongiotic, granulomatous (sarcoidal/foreign-body), pseudolymphomatous, pseudoepitheliomatous hyperplasia"]),
 ("How do you evaluate a tattoo reaction?", ["History — colour involved, timing, sun exposure, systemic symptoms", "Biopsy; culture for mycobacteria if papulopustules within weeks; patch test (pigment series, PPD); chest X-ray/ACE for sarcoid; HBV/HCV/HIV serology for amateur tattoos"]),
 ("Treatment of tattoo reactions.", ["Topical/intralesional steroids, tacrolimus; hydroxychloroquine/allopurinol for granulomatous; systemic therapy for sarcoidosis", "Excision or laser removal for persistent allergy (caution — Q-switched laser can release allergen and trigger systemic reaction)", "Antimicrobials as per culture (NTM — clarithromycin)"]),
 ("Methods of tattoo removal.", ["Q-switched lasers (nanosecond) and picosecond lasers — selective photothermolysis/ photoacoustic shattering of pigment, cleared by macrophages; wavelength by colour: black — 1064 nm Nd:YAG/755 nm alexandrite; red — 532 nm KTP; green — 755/694 nm ruby", "Multiple sessions 6–8 weeks apart; the R20 method (repeated passes) and perfluorodecalin patches", "Side effects: hypo/hyperpigmentation, paradoxical darkening of cosmetic tattoos (white/flesh — titanium/iron oxide turns black), scarring, allergic reactions", "Older: excision, dermabrasion, salabrasion, CO2 laser — scar"]),
 ("What is paradoxical darkening?", ["Laser reduction of ferric oxide (rust, flesh, white tones) to black ferrous oxide — common with cosmetic lip/eyebrow tattoos; test spot first"]),
 ],
 spot=["Reaction confined to red part of tattoo — allergy to mercury/azo red pigment", "Black henna — PPD sensitisation", "Granulomas in tattoo — look for sarcoidosis"]),

dict(case="Urticaria & angioedema", src=f"{PYQ}; {IA} (Urticaria); EAACI/GA²LEN/EuroGuiDerm/APAAACI urticaria guideline 2022",
 qa=[
 ("Define urticaria and angioedema.", ["Urticaria: transient itchy wheals — central swelling with surrounding flare, each lasting <24 h and leaving no mark — due to dermal oedema", "Angioedema: deeper swelling of dermis/subcutis/mucosa, more painful than itchy, lasting up to 72 h", "Either or both may occur"]),
 ("Classify urticaria (PYQ).", ["Acute (<6 weeks) vs chronic (≥6 weeks)", "Chronic spontaneous urticaria (CSU): no specific trigger — autoimmune (type I autoallergic with IgE against self antigens like TPO/IL-24; type IIb autoimmune with IgG against IgE/FcεRI) or unknown", "Chronic inducible urticaria (CIndU): physical — symptomatic dermographism (commonest), cold, delayed pressure, solar, heat, vibratory; non-physical — cholinergic, contact, aquagenic", "Others/related: urticarial vasculitis, autoinflammatory syndromes (CAPS, Schnitzler), urticaria pigmentosa (mastocytosis), hereditary angioedema (no wheals)"]),
 ("Pathogenesis.", ["Mast cell degranulation (immunological IgE/autoantibody, complement C5a, neuropeptides, drugs like opioids/contrast, NSAIDs via COX-1 inhibition) → histamine, prostaglandin D2, leukotrienes, PAF, cytokines → vasodilation and vascular leak", "Bradykinin-mediated angioedema (no wheals, no itch): hereditary/acquired C1-inhibitor deficiency, ACE inhibitors"]),
 ("Causes of acute urticaria.", ["Idiopathic (~50%), infections (viral URTI in children — commonest), drugs (penicillins, NSAIDs, opioids, contrast), foods (nuts, shellfish, eggs, milk), insect stings, latex, blood products"]),
 ("Investigations — guideline approach.", ["Acute: none routinely unless a specific allergen is suspected", "Chronic spontaneous: limited — CBC with differential, ESR/CRP, total IgE and IgG anti-TPO (predict response to omalizumab/cyclosporine), ± basophil activation test/autologous serum skin test", "Further tests only if history suggests: thyroid function, H. pylori, stool for parasites, tryptase, skin biopsy (wheals >24 h — urticarial vasculitis), complement C4 and C1-INH for angioedema without wheals", "Provocation tests for CIndU: FricTest for dermographism, ice-cube/TempTest for cold, exercise/hot-bath for cholinergic, weighted rods for delayed pressure, phototest for solar"]),
 ("Write a short note on cold urticaria (PYQ).", ["Wheals on cold exposure (cold air, water, drinks — lips/throat swelling), develop on rewarming", "Primary (acquired idiopathic) or secondary (cryoglobulins, cold agglutinins, infections — EBV, HIV, hepatitis)", "Ice-cube test: 5 min on forearm, read after 10 min — wheal positive; TempTest for threshold", "Risk: anaphylaxis/drowning with whole-body immersion (swimming) — carry epinephrine", "Treatment: avoid cold, high-dose non-sedating antihistamines, omalizumab; familial cold autoinflammatory syndrome (NLRP3) is different — fever, rash, arthralgia after cold; treat with IL-1 blockers"]),
 ("What is cholinergic urticaria?", ["Tiny (1–3 mm) itchy wheals with large flares after rise in core body temperature — exercise, hot shower, spicy food, emotion; young adults; sweat allergy and hypohidrosis implicated", "Exercise/hot-water test; non-sedating antihistamines, propranolol, omalizumab; exercise-induced anaphylaxis is a separate entity (food-dependent — wheat ω-5 gliadin)"]),
 ("Differentiate urticaria from urticarial vasculitis.", ["Urticarial vasculitis: individual lesions last >24 h, burn/pain more than itch, leave purpura/bruising/pigmentation, systemic features (arthralgia, fever, kidney, eye, lung), low complement in hypocomplementaemic form (anti-C1q, SLE association)", "Biopsy: leukocytoclastic vasculitis; treatment — dapsone, colchicine, HCQ, steroids, immunosuppressants"]),
 ("Management of chronic urticaria — the stepwise guideline.", ["Avoid triggers (NSAIDs, alcohol, tight clothing, physical triggers), treat underlying cause if found", "Step 1: standard-dose second-generation H1 antihistamine daily (cetirizine, levocetirizine, fexofenadine, bilastine, desloratadine, rupatadine) — not on demand", "Step 2: increase up to 4-fold dose after 2–4 weeks if not controlled", "Step 3: add omalizumab (anti-IgE) 300 mg SC every 4 weeks (may increase dose/frequency if needed)", "Step 4: cyclosporine 3.5–5 mg/kg/day (with antihistamine) if omalizumab fails", "Short oral steroid courses (≤10 days) only for severe exacerbations; montelukast, dapsone, HCQ, H2 blockers have weak evidence", "Newer: dupilumab and the BTK inhibitor remibrutinib approved for CSU in some countries (confirm in India)"]),
 ("Assessment tools.", ["UAS7 (urticaria activity score over 7 days: wheals 0–3 + itch 0–3 per day, max 42), UCT (urticaria control test, ≥12 controlled), AAS (angioedema activity), CU-Q2oL (quality of life)"]),
 ("What is hereditary angioedema (HAE)?", ["Autosomal dominant deficiency (type I — low C1-INH level, ~85%) or dysfunction (type II — normal/high level but non-functional) of C1 esterase inhibitor; HAE with normal C1-INH (factor XII, plasminogen mutations, oestrogen-dependent)", "Recurrent non-itchy, non-pitting swellings of skin, gut (colic, vomiting), larynx (fatal asphyxia) without wheals; triggers — trauma, dental work, stress, oestrogens, ACE inhibitors", "Screening: low C4 (also during attacks); C1-INH level and function", "Treatment: antihistamines/steroids/adrenaline do NOT work; acute — C1-INH concentrate, icatibant (bradykinin B2 antagonist), ecallantide, fresh frozen plasma; prophylaxis — lanadelumab (anti-kallikrein), berotralstat, C1-INH, danazol, tranexamic acid"]),
 ("What is ACE-inhibitor angioedema?", ["Bradykinin accumulation from reduced breakdown — face, lips, tongue swelling without wheals; may occur after years of use; commoner in Black patients; stop the drug (also avoid ARBs cautiously); icatibant in severe cases"]),
 ("How do you treat acute urticaria and anaphylaxis?", ["Acute urticaria: non-sedating antihistamine (up to 4×) ± short prednisolone course", "Anaphylaxis: adrenaline 0.5 mg (0.5 ml of 1:1000) IM in anterolateral thigh (child 0.01 mg/kg, max 0.5 mg), repeat after 5 min if needed; airway, oxygen, IV fluids, then antihistamine and steroid; observe ≥6–12 h; prescribe adrenaline auto-injector"]),
 ("What is dermographism?", ["Wheal along a line of firm stroking within minutes (Darier's sign is the same in mastocytosis lesions); symptomatic dermographism is the commonest CIndU — FricTest; antihistamines"]),
 ("Prognosis of CSU.", ["About 50% remit in 1–5 years; severe disease, angioedema, autoimmunity and positive ASST predict longer course"]),
 ],
 spot=["Individual wheal <24 h and leaves no mark = urticaria; >24 h with bruising = urticarial vasculitis", "Angioedema without wheals + abdominal pain + low C4 — HAE (no response to antihistamines)", "Step up: antihistamine ×4 → omalizumab → cyclosporine"]),

dict(case="Stevens–Johnson syndrome / TEN", src=f"{PYQ}; {IA} (SJS/TEN); SCORTEN; ALDEN; Indian SJS-TEN consensus",
 qa=[
 ("Define SJS and TEN and classify by BSA.", ["Severe life-threatening mucocutaneous reactions, mostly drug-induced, with extensive keratinocyte death (epidermal necrosis) and detachment", "SJS: <10% body surface area (BSA) detachment; SJS–TEN overlap: 10–30%; TEN: >30% (Bastuji-Garin classification)", "Lesions: widespread dusky/purpuric macules, flat atypical targets, blisters; ≥2 mucosal sites"]),
 ("Common culprit drugs (India).", ["Antiepileptics — carbamazepine (commonest in India), phenytoin, phenobarbital, lamotrigine", "Allopurinol (high risk, HLA-B*58:01), sulphonamides (cotrimoxazole), nevirapine, NSAIDs (oxicams), fluoroquinolones, β-lactams, anti-TB drugs, sulfasalazine, dapsone", "Onset typically 4–28 days after starting the drug (first exposure)", "Mycoplasma pneumoniae is a non-drug cause in children; ~5% idiopathic"]),
 ("What are the HLA associations?", ["HLA-B*15:02 with carbamazepine (and oxcarbazepine, phenytoin) in Han Chinese, Thai, Malay and some Indian populations — US FDA advises screening before starting carbamazepine in at-risk ancestry", "HLA-B*58:01 with allopurinol; HLA-A*31:01 with carbamazepine DRESS/SJS in Europeans and Japanese; HLA-B*13:01 with dapsone hypersensitivity syndrome"]),
 ("Explain the pathogenesis.", ["Drug (or metabolite) presented by specific HLA → activates drug-specific cytotoxic CD8+ T cells and NK cells (p-i concept, altered peptide repertoire)", "Keratinocyte apoptosis/necroptosis by granulysin (key mediator; levels correlate with severity), perforin–granzyme B, Fas–FasL, TNF-α, annexin A1", "Massive keratinocyte death → full-thickness epidermal necrosis and subepidermal split"]),
 ("Clinical features.", ["Prodrome 1–3 days: fever, sore throat, conjunctivitis, malaise, painful skin (cutaneous pain is an early warning)", "Rash starts on face and upper trunk → spreads; dusky erythematous/purpuric macules and flat atypical targets that coalesce, flaccid blisters, sheets of detached skin ('wet cigarette paper')", "Nikolsky sign and Asboe-Hansen sign positive on erythematous skin", "Mucosa (>90%): haemorrhagic crusting of lips, oral erosions, purulent conjunctivitis/pseudomembranes, genital erosions; also respiratory and GI epithelium"]),
 ("Write a short note on Nikolsky sign (PYQ).", ["Shearing pressure on apparently normal/ perilesional skin causes separation of the epidermis", "Positive in pemphigus (intraepidermal acantholysis), SSSS, TEN (on erythematous skin), also EB, bullous impetigo; negative in bullous pemphigoid", "Variants: Nikolsky I (marginal — at blister edge), Nikolsky II (on normal skin away), Asboe-Hansen (bulla spread), pseudo-Nikolsky (TEN — on erythematous skin only)"]),
 ("Differential diagnosis.", ["EM major (typical/raised targets, acral, HSV, less mucosal and no extensive detachment)", "SSSS (children, superficial split, no mucosa, sterile blister, tender erythema, flexural accentuation)", "GBFDE, AGEP (pustules), DRESS, linear IgA bullous dermatosis (drug — vancomycin), paraneoplastic pemphigus, bullous lupus/TEN-like lupus, GVHD grade IV, toxic shock syndrome, phototoxic reaction, burns, Kawasaki disease, MIRM"]),
 ("How do you identify the culprit drug?", ["Detailed drug chart with exact start dates; ALDEN algorithm (Algorithm of Drug causality for Epidermal Necrolysis — time delay, drug presence, prechallenge/rechallenge, dechallenge, drug notoriety, other causes; score ≥6 very probable)", "In vitro tests (lymphocyte transformation test, ELISpot granulysin) — research; rechallenge contraindicated; patch test low sensitivity"]),
 ("Investigations.", ["Skin biopsy (frozen section for rapid diagnosis): full-thickness epidermal necrosis, subepidermal split, sparse dermal infiltrate; DIF negative (excludes autoimmune bullous)", "CBC, renal function, electrolytes, bicarbonate, glucose, LFT, albumin, CRP, blood/skin/urine cultures, chest X-ray, ABG", "Mycoplasma serology/PCR in children; HLA testing if relevant"]),
 ("What is SCORTEN? (prognostic score)", ["Calculated within 24 h of admission and at day 3; one point each: age ≥40 years; associated malignancy; heart rate ≥120/min; epidermal detachment >10% BSA on day 1; serum urea >10 mmol/L (≈28 mg/dL BUN); serum glucose >14 mmol/L (252 mg/dL); serum bicarbonate <20 mmol/L", "Predicted mortality: 0–1: ~3%; 2: ~12%; 3: ~35%; 4: ~58%; ≥5: >90%"]),
 ("Supportive management (the backbone).", ["Immediately stop the culprit (and all non-essential drugs) — earlier withdrawal improves survival", "Admit to burns unit/ICU if SCORTEN ≥3 or >10% detachment; barrier nursing, warm room (30–32 °C), air-fluidised bed", "Fluids: lower than burns (≈ 2 ml/kg/%BSA + maintenance), guided by urine output 0.5–1 ml/kg/h; electrolytes; nutrition by nasogastric tube (high-protein, early)", "Skin care: leave blisters in place (biological dressing), non-adherent dressings (paraffin gauze, silicone, Mepitel), avoid adhesive tapes, silver dressings; no prophylactic systemic antibiotics — cultures and treat sepsis", "Eyes: daily ophthalmology review, lubricants, topical steroid/antibiotic drops, lysis of synechiae, amniotic membrane transplantation for severe ocular disease", "Mouth: oral rinses, white soft paraffin to lips; genital care (prevent synechiae — vaginal moulds); analgesia; DVT prophylaxis; stress ulcer prophylaxis; respiratory monitoring"]),
 ("Specific (immunomodulatory) therapy.", ["Cyclosporine 3–5 mg/kg/day for 7–10 days then taper — preferred first-line in our protocol and many Indian/European centres (inhibits CD8 T cell activation; studies show reduced mortality vs predicted SCORTEN)", "Systemic corticosteroids: early short pulse (e.g. dexamethasone/methylprednisolone) — controversial; many Indian centres use within the first 72 h", "Etanercept (TNF-α blocker) 25–50 mg SC single/two doses — RCT showed faster healing and lower mortality vs steroids", "IVIG (2–3 g/kg over 3–4 days) — conflicting evidence; combinations (steroid + IVIG) used", "Plasmapheresis, N-acetylcysteine (adjunct) — limited data", "Thalidomide is contraindicated (increased mortality in RCT)"]),
 ("What are the acute and long-term complications?", ["Acute: sepsis (commonest cause of death — S. aureus, Pseudomonas), fluid/electrolyte imbalance, hypothermia, acute kidney injury, hypoalbuminaemia, ARDS/bronchial sloughing, GI bleeding, hepatitis, DVT/pulmonary embolism, ileus", "Long-term (in ~50%): eyes — dry eye, symblepharon, trichiasis, entropion, corneal scarring, blindness; skin — dyspigmentation, scarring, eruptive naevi, nail loss, hypohidrosis; mucosal — oral, oesophageal, urethral, vaginal strictures; lungs — bronchiolitis obliterans; psychological (PTSD)"]),
 ("How do you prevent recurrence and educate?", ["Give a drug-allergy card/medical alert bracelet listing culprit and structurally related drugs (e.g. aromatic antiepileptics cross-react: carbamazepine, phenytoin, phenobarbital, oxcarbazepine — use levetiracetam/valproate)", "Report to pharmacovigilance (PvPI — ADR monitoring centre in India)", "HLA screening before high-risk drugs in at-risk groups; first-degree relatives may share HLA risk", "Start allopurinol at low dose, avoid unnecessary use (asymptomatic hyperuricaemia)"]),
 ("How do you classify cutaneous adverse drug reactions?", ["Immediate (type I, IgE): urticaria, angioedema, anaphylaxis", "Delayed T-cell (type IV): IVa — eczematous (Th1), IVb — DRESS/maculopapular with eosinophils (Th2), IVc — SJS/TEN, FDE (cytotoxic T cells), IVd — AGEP (neutrophil, IL-8)", "Severe cutaneous adverse reactions (SCARs): SJS/TEN, DRESS, AGEP, GBFDE"]),
 ("Compare DRESS with SJS/TEN briefly.", ["DRESS: latency 2–8 weeks, morbilliform rash with facial oedema, fever, lymphadenopathy, eosinophilia/atypical lymphocytes, internal organ involvement (liver commonest), HHV-6 reactivation; RegiSCAR score; systemic steroids mainstay with slow taper", "SJS/TEN: latency 4–28 days, epidermal necrosis and mucositis, cytotoxic T cell mediated, SCORTEN for prognosis"]),
 ("Prognosis.", ["Mortality: SJS ~1–5%, overlap ~10–15%, TEN 25–35% (higher in elderly, extensive disease, delayed drug withdrawal)", "Re-epithelialisation usually in 2–3 weeks; mucosal and ocular sequelae may be lifelong"]),
 ],
 spot=["Painful skin + purpuric flat targets + ≥2 mucosae after carbamazepine — SJS/TEN", "SCORTEN 7 points (age ≥40, cancer, HR ≥120, BSA >10%, urea >10, glucose >14, bicarbonate <20)", "HLA-B*15:02 — carbamazepine"],
 note="Cyclosporine first-line follows our department decision; steroid use varies between centres."),
]
